begin;
set local search_path=public,extensions;
select plan(33);
select has_table('public','studio_scenario_versions','Versioned scenarios exist');
select has_table('public','studio_worksheets','Owner heads exist');
select has_table('public','studio_worksheet_revisions','Immutable revisions exist');
select is((select experience_kind from public.course_versions where id='system-design-studio-v1'),'studio','Course uses Studio experience');
insert into auth.users(id,email) values('a4600000-0000-0000-0000-000000000001','studio-policy-a@example.test'),('a4600000-0000-0000-0000-000000000002','studio-policy-b@example.test'),('a4600000-0000-0000-0000-000000000005','studio-policy-staff@example.test');
insert into public.staff_roles(user_id,role) values('a4600000-0000-0000-0000-000000000005','admin');
update public.profiles set goal='Learn careful workload estimation' where user_id in ('a4600000-0000-0000-0000-000000000001','a4600000-0000-0000-0000-000000000002','a4600000-0000-0000-0000-000000000005');
set local role anon;
select throws_ok($$select public.get_studio_workshop('system-design-studio-v1','campus-events-v1')$$,'42501','permission denied for function get_studio_workshop','Anonymous RPC denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','a4600000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.enrol_course('system-design-studio-v1')$$,'No JavaScript prerequisite');
select is(public.save_studio_worksheet('campus-events-v1',0,'a4600000-0000-0000-0000-000000000003','{"functionalRequirements":"Browse events","exclusions":"Ticketing","latencyTargetMs":200,"availabilityTargetPercent":99.9,"assumptions":"Illustrative defaults","explanation":"","workload":{"dailyActiveUsers":100000,"requestsPerUserPerDay":20,"peakFactor":5,"readPercentage":90,"readResponseBytes":20000,"writePayloadBytes":2000,"retentionDays":30}}'::jsonb)->>'revision','1','First revision saved');
select is(public.save_studio_worksheet('campus-events-v1',0,'a4600000-0000-0000-0000-000000000003','{"functionalRequirements":"Browse events","exclusions":"Ticketing","latencyTargetMs":200,"availabilityTargetPercent":99.9,"assumptions":"Illustrative defaults","explanation":"","workload":{"dailyActiveUsers":100000,"requestsPerUserPerDay":20,"peakFactor":5,"readPercentage":90,"readResponseBytes":20000,"writePayloadBytes":2000,"retentionDays":30}}'::jsonb)->>'revision','1','Identical retry returned original');
select is((select count(*) from public.studio_worksheet_revisions),1::bigint,'Retry saved once');
select throws_ok($$select public.save_studio_worksheet('campus-events-v1',0,'a4600000-0000-0000-0000-000000000004','{"functionalRequirements":"Browse events","exclusions":"Ticketing","latencyTargetMs":200,"availabilityTargetPercent":99.9,"assumptions":"Illustrative defaults","explanation":"","workload":{"dailyActiveUsers":100000,"requestsPerUserPerDay":20,"peakFactor":5,"readPercentage":90,"readResponseBytes":20000,"writePayloadBytes":2000,"retentionDays":30}}'::jsonb)$$,'40001','A newer worksheet revision exists','Stale revision rejected');
select set_config('request.jwt.claim.sub','a4600000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.studio_worksheet_revisions),0::bigint,'Other learner sees no revisions');
select is((select count(*) from public.attempts),0::bigint,'Saving awarded no practice grade');
reset role;
select ok(has_function_privilege('authenticated','public.save_studio_worksheet(text,integer,uuid,jsonb)','EXECUTE'),'Authenticated save grant exists');
select ok(not has_table_privilege('authenticated','public.studio_worksheet_revisions','INSERT'),'Direct revision insertion denied');
select ok(not has_table_privilege('authenticated','public.studio_worksheet_revisions','UPDATE'),'Revision updates denied');
select ok(not has_table_privilege('authenticated','public.studio_worksheets','DELETE'),'Direct head deletion denied');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('public.studio_worksheets'::regclass,'public.studio_worksheet_revisions'::regclass)),'Both private tables enforce RLS');
select ok(exists(select 1 from pg_constraint where conrelid='public.studio_worksheet_revisions'::regclass and confrelid='public.studio_worksheets'::regclass and contype='f' and cardinality(conkey)=2 and confdeltype='c'),'Revision belongs to composite owner/scenario head with deletion cascade');
select is((select schema_version||'/'||formula_version from public.studio_scenario_versions where id='campus-events-v1' and course_id='system-design-studio-v1'),'worksheet-v1/capacity-v1','Scenario pins schema and formula to Studio course');
select is((select count(*) from public.course_versions where id like 'javascript-%' and experience_kind<>'lessons'),0::bigint,'Existing JavaScript courses retain lesson experience');
set local role authenticated;
select set_config('request.jwt.claim.sub','a4600000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.get_studio_workshop('javascript-foundations-v2','campus-events-v1')$$,'22023','Unknown workshop','Unrelated course association rejected');
select throws_ok($$select public.save_studio_worksheet('campus-events-v2',1,gen_random_uuid(),'{}'::jsonb)$$,'22023','Unsupported workshop version','Unsupported scenario rejected');
select throws_ok($$select public.save_studio_worksheet('campus-events-v1',0,'a4600000-0000-0000-0000-000000000003',jsonb_set((select worksheet from public.studio_worksheet_revisions where revision=1),'{explanation}','"Conflicting reuse"'))$$,'22023','Save request already used for different work','Idempotency key cannot be reused for changed evidence');
select throws_ok($$select public.save_studio_worksheet('campus-events-v1',1,gen_random_uuid(),(select worksheet||'{"estimates":{"peakRps":0}}'::jsonb from public.studio_worksheet_revisions where revision=1))$$,'22023','Use the supported worksheet fields','Caller cannot supply computed results');
select is((select worksheet->'workload'->>'dailyActiveUsers' from public.studio_worksheet_revisions where revision=1),'100000','Original immutable revision retains submitted workload');
select is(jsonb_array_length(public.export_learner_data()->'studio_worksheet_revisions'),1,'Export includes owned saved revision');
select ok(not (public.export_learner_data()->'studio_worksheet_revisions'->0 ? 'user_id'),'Export omits internal owner identifiers');
select set_config('request.jwt.claim.sub','a4600000-0000-0000-0000-000000000002',true);
select is((select count(*) from public.studio_worksheets),0::bigint,'Second learner cannot read another head');
select set_config('request.jwt.claim.sub','a4600000-0000-0000-0000-000000000005',true);
select is((select count(*) from public.studio_worksheet_revisions),0::bigint,'Unrelated staff cannot read private revisions');
select is(jsonb_array_length(public.export_learner_data()->'studio_worksheet_revisions'),0,'Staff export contains no other learner evidence');
reset role;
delete from auth.users where id='a4600000-0000-0000-0000-000000000001';
select is((select count(*) from public.studio_worksheets where user_id='a4600000-0000-0000-0000-000000000001'),0::bigint,'Synthetic Auth deletion cascades worksheet head');
select is((select count(*) from public.studio_worksheet_revisions where user_id='a4600000-0000-0000-0000-000000000001'),0::bigint,'Synthetic Auth deletion cascades revisions');
select is((select count(*) from auth.users where id in ('a4600000-0000-0000-0000-000000000002','a4600000-0000-0000-0000-000000000005')),2::bigint,'Other synthetic accounts survive');
select * from finish();
rollback;
